head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.setHeader();
        $c.cm.PanelToGroupBox(panel_Item_1);
        $c.cm.PanelToGroupBox(panel_Top_1);
        $c.cm.PanelToGroupBox(panel_Top_2);
        await scwin.listSync1();
        await scwin.listSync2();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41100.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Save_1_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_1_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41100.btn_Save_1_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_1_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_1_onclick = async function() {
    try {
        await scwin.listSync1();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41100.btn_Search_1_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_2_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
