};

/**
 * @method
 * @name btn_New_2_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_2_onclick = async function() {
    try {
        const options = {
            id: "ULDSTF41101",
            title: " ELW 기초자산명 등록",
            type: "browserPopup",
            width: "780px",
            height: "400px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("../lstmgt/ULDSTF41101.gfm", options);
        await scwin.listSync2();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41100.btn_New_2_onclick" });
    }
};

/**
 * @method
 * @name dts_List_1_OnLoadCompleted
 * @description dts_List_1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page_1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41100.dts_List_1_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_1_OnLoadError
 * @description dts_List_1 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_1_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List_1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41100.dts_List_1_OnLoadError" });
    }
};

/**
 * @method
 * @name grd_List_1_OnClick
 * @description grd_List_1 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_1_OnClick = function(row, colid) {
    try {
        scwin.readSync1(row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41100.grd_List_1_OnClick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        $c.lc.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41100.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        await scwin.listSync1();
        dts_Isu_1.reset();
        dts_Isu_1.insertRow();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41100.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name dts_List_2_OnLoadCompleted
 * @description dts_List_2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
