    }
};

/**
 * @method
 * @name btn_Excel_1_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_1_onclick = function() {
    try {
        // 엑셀 로그
        $c.stf.doLogSave("ULDSTF41100.xml", SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List_1, {fileName: "ELW 발행회사 목록", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41100.btn_Excel_1_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_2_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_2_onclick = function() {
    try {
        // 엑셀 로그
        $c.stf.doLogSave("ULDSTF41100.xml", SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List_2, {fileName: "ELW 기초자산 목록", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41100.btn_Excel_2_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_1_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_1_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41100.btn_Close_1_onclick" });
    }
};

/**
