/**
 * @method
 * @name cmb_IDX_TP_CD_onselchange
 * @description cmb_IDX_TP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_IDX_TP_CD_onselchange = function() {
    try {
