///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync1
 * @description list Sync1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync1 = async function() {
    const sbmOptions = {
        id : "sbm_dts_List_1",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List_1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_Isu_1",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Isu_1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Isu_1.insertRow();
    // alert(dts_Isu_1.text+" dts_Isu_1.text");

};

/**
 * @method
 * @name listSync2
 * @description list Sync2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync2 = async function() {
    url += "&IDX_TP_CD=" + cmb_IDX_TP_CD.BindColVal;
    url += "&COM_NM=" + txb_ComNm.getValue();
    const sbmOptions = {
        id : "sbm_dts_List_2",
        action : "/ELWUnderlyingAsset.do",
        ref : "",
        target : "dts_List_2=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    let TR_JOB;
    TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(TR_JOB)) return;

        // alert('[dts_Uly]'+dts_Uly.text);
        trs_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/ELWUnderlyingAsset.do",
            ref : "dts_Isu_1",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name readSync1
 * @description read Sync1 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.readSync1 = function(row) {
    dts_Isu_1.setCellData(1, "ISUR_CD", dts_List_1.getCellData(row, "ISUR_CD"));
    dts_Isu_1.setCellData(1, "LIST_STAT_CD", dts_List_1.getCellData(row, "LIST_STAT_CD"));
    dts_Isu_1.setCellData(1, "COM_NM", dts_List_1.getCellData(row, "COM_NM"));
    dts_Isu_1.setCellData(1, "COM_ENG_NM", dts_List_1.getCellData(row, "COM_ENG_NM"));
    dts_Isu_1.setCellData(1, "WRNT_ISUR_CD", dts_List_1.getCellData(row, "WRNT_ISUR_CD"));
    dts_Isu_1.setCellData(1, "WRNT_ISUR_NM", dts_List_1.getCellData(row, "WRNT_ISUR_NM"));
    dts_Isu_1.setCellData(1, "WRNT_ISUR_ENG_NM", dts_List_1.getCellData(row, "WRNT_ISUR_ENG_NM"));
    dts_Isu_1.setCellData(1, "ELW_ISUR_REG_DD", dts_List_1.getCellData(row, "ELW_ISUR_REG_DD"));
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("[회사]를 선택하세요.");
        txb_ISUR_CD.focus();
        return false;
    }
    if (!$c.stf.checkEmptyValue(txb_WRNT_ISUR_NM, "한글발행사종목명")) return false;
    if (!$c.stf.checkMaxLength(txb_WRNT_ISUR_NM, 6, "한글발행사종목명")) return false;
    if (!$c.stf.checkEmptyValue(txb_WRNT_ISUR_ENG_NM, "영문발행사종목명")) return false;
    if (!$c.stf.checkMaxLength(txb_WRNT_ISUR_ENG_NM, 6, "영문발행사종목명")) return false;
    return true;
};

/**
 * @method
 * @name changeText
 * @description 지수구분이 KOSPI200이면 TEXTBOX의 메시지를 바꾼다.
 * @returns {void}
 * @hidden N
 */
scwin.changeText = function() {
    const val = cmb_IDX_TP_CD.BindColVal;
    if (val === '1') {
        textbox_1.setValue("- KOSPI100은 ELW 기초자산이 아니며 참고용임.");
        textbox_1.style.color = 'FF0000';
    } else {
        textbox_1.setValue("- 기초자산명은 ELW 종목약명에 사용됩니다.");
        textbox_1.style.color = '#808080';
    }
};
